solutions.naive:
class Solution:
    def maximumCandies(self, candies: list[int], k: int) -> int:
        for size in range(max(candies), 0, -1):
            served = 0
            for c in candies:
                served += c // size
            if served >= k:
                return size
        return 0

solutions.better:
class Solution:
    def maximumCandies(self, candies: list[int], k: int) -> int:
        lo, hi = 1, max(candies)
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            served = sum(c // mid for c in candies)
            if served >= k:
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

solutions.optimal:
class Solution:
    def maximumCandies(self, candies: list[int], k: int) -> int:
        hi = min(max(candies), sum(candies) // k)
        if hi == 0:
            return 0
        lo = 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            served = 0
            for c in candies:
                served += c // mid
                if served >= k:
                    break
            if served >= k:
                lo = mid
            else:
                hi = mid - 1
        return lo

